const body = $('Webhook').first().json.body;
const text = body.text;
const model = body.model || 'gpt-4o';

// Approximate token counting based on model family
// These are estimates - actual counts may vary slightly

// Character-based estimation for different encodings
const estimateTokens = (text, encoding) => {
  // GPT-4/3.5 use cl100k_base encoding (~4 chars per token for English)
  // GPT-2 uses gpt2 encoding (~4 chars per token)
  // Claude uses similar tokenization

  const charCount = text.length;
  const wordCount = text.split(/\s+/).filter(w => w.length > 0).length;

  // Different ratios for different content types
  const hasCode = /[{}\[\]();=<>]/.test(text);
  const hasCJK = /[\u4e00-\u9fff\u3040-\u309f\u30a0-\u30ff]/.test(text);
  const hasEmoji = /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}]/u.test(text);

  let charsPerToken;

  if (hasCJK) {
    // CJK characters are typically 1-2 tokens each
    charsPerToken = 1.5;
  } else if (hasCode) {
    // Code tends to have more tokens per character
    charsPerToken = 3;
  } else {
    // English text averages ~4 chars per token
    charsPerToken = 4;
  }

  const estimatedTokens = Math.ceil(charCount / charsPerToken);

  return {
    estimated_tokens: estimatedTokens,
    char_count: charCount,
    word_count: wordCount,
    avg_word_length: wordCount > 0 ? (charCount / wordCount).toFixed(2) : 0,
    has_code: hasCode,
    has_cjk: hasCJK,
    has_emoji: hasEmoji,
    chars_per_token_estimate: charsPerToken
  };
};

// Model context limits
const MODEL_LIMITS = {
  'gpt-4o': 128000,
  'gpt-4o-mini': 128000,
  'gpt-4-turbo': 128000,
  'gpt-4': 8192,
  'gpt-3.5-turbo': 16385,
  'claude-3-opus': 200000,
  'claude-3-sonnet': 200000,
  'claude-3-haiku': 200000,
  'claude-3.5-sonnet': 200000,
  'mistral-large': 128000,
  'mistral-small': 32000,
  'gemini-1.5-pro': 1000000,
  'gemini-1.5-flash': 1000000
};

const analysis = estimateTokens(text, model);
const contextLimit = MODEL_LIMITS[model] || 128000;
const usagePercent = ((analysis.estimated_tokens / contextLimit) * 100).toFixed(2);

return [{
  json: {
    success: true,
    data: {
      model: model,
      estimated_tokens: analysis.estimated_tokens,
      context_limit: contextLimit,
      usage_percent: parseFloat(usagePercent),
      fits_context: analysis.estimated_tokens < contextLimit,
      remaining_tokens: Math.max(0, contextLimit - analysis.estimated_tokens),
      statistics: {
        char_count: analysis.char_count,
        word_count: analysis.word_count,
        avg_word_length: parseFloat(analysis.avg_word_length),
        chars_per_token: analysis.chars_per_token_estimate
      },
      content_type: {
        has_code: analysis.has_code,
        has_cjk: analysis.has_cjk,
        has_emoji: analysis.has_emoji
      }
    },
    meta: {
      provider: 'tokenizer',
      note: 'Token counts are estimates. Actual counts may vary by ~5-10%.'
    }
  }
}];

